<?phpnamespace app\api\service\business;use app\api\service\CommService;use app\common\model\MallRegion;class RegionService extends CommService{    public function __construct($param, $user_info)    {        parent::_initialize($param, $user_info);    }    public function getCityList($city_arr = [])    {        $city_list = [];        $province = $this->getProvinceList();        $list = MallRegion::where('level', 2)            ->where('status', 1)            ->whereIn('region_id', $city_arr)            ->field('region_id,region_name,pid')            ->cache(true)            ->select();        foreach ($list as $key => $value) {            $province_name = '';            if (isset($province[$value['pid']])) {                $province_name = $province[$value['pid']]['region_name'] . '-';            }            $city_list[$key]['region_id'] = $value['region_id'];            $city_list[$key]['region_name'] = $province_name . $value['region_name'];        }        $this->data['city_list'] = $city_list ?? [];        return $this->data;    }    protected function getProvinceList()    {        return MallRegion::where('level', 1)->cache(true)->column('region_id,region_name', 'region_id');    }}